:root {
    --bg: #07111e;
    --panel: #0b1829;
    --card: #0f2036;
    --card2: #13294a;
    --border: #1f3350;
    --text: #e6edf7;
    --dim: #c7d6ec;
    --faint: #9cb0cf;
    --accent: #7c9eff;
    --accent2: #4a6fd6;
    --ok: #86efac;
    --warn: #fdba74;
    --ng: #fca5a5;
    --sw: 280px;
    --font:
        'Noto Sans JP', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    --mono: 'JetBrains Mono', Consolas, 'Courier New', monospace;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--font);
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}
a {
    color: var(--accent);
    text-decoration: none;
}
a:hover {
    text-decoration: underline;
}
.layout {
    display: block;
}
.sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: var(--sw);
    background: var(--panel);
    border-right: 1px solid var(--border);
    overflow-y: auto;
    padding: 22px 14px 40px;
    z-index: 50;
    transition: transform 0.25s;
}
.side-title {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--accent);
    text-transform: uppercase;
    margin: 0 8px 4px;
}
.side-sub {
    font-size: 13px;
    color: var(--faint);
    margin: 0 8px 16px;
    line-height: 1.5;
}
.sidebar ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sidebar li {
    margin: 2px 0;
}
.sidebar a {
    display: block;
    padding: 7px 10px;
    border-radius: 8px;
    color: var(--dim);
    font-size: 13.5px;
    line-height: 1.45;
    border-left: 3px solid transparent;
}
.sidebar a:hover {
    background: var(--card);
    text-decoration: none;
    color: #fff;
}
.sidebar a.active {
    background: var(--card2);
    color: #fff;
    border-left-color: var(--accent);
    font-weight: 700;
}
.nav-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 60;
    width: 42px;
    height: 42px;
    border-radius: 10px;
    border: 1px solid var(--border);
    background: var(--panel);
    color: var(--text);
    font-size: 20px;
    cursor: pointer;
}
.scrim {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.55);
    z-index: 40;
}
.main {
    margin-left: var(--sw);
    padding: 0 48px 80px;
}
.hero {
    position: relative;
    padding: 56px 0 32px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 28px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -80px;
    width: 520px;
    height: 420px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.22), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    padding: 5px 14px;
    border-radius: 999px;
    border: 1px solid var(--accent2);
    background: rgba(124, 158, 255, 0.12);
    color: var(--accent);
    font-size: 12.5px;
    font-weight: 700;
    letter-spacing: 0.06em;
    margin-bottom: 16px;
}
.hero-title {
    text-wrap: balance;
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    margin: 0 0 20px;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    gap: 0;
    margin: 0 0 18px;
}
.hero-meta .m {
    padding: 4px 22px 4px 0;
    margin-right: 22px;
    border-right: 1px solid var(--border);
}
.hero-meta .m:last-child {
    border-right: none;
}
.hero-meta .l {
    display: block;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--faint);
}
.hero-meta .v {
    display: block;
    font-size: 14.5px;
    color: var(--text);
}
.hero-links {
    border-top: 1px solid var(--border);
    padding-top: 14px;
    font-size: 14px;
    color: var(--dim);
}
.main h2 {
    font-size: 24px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding-bottom: 10px;
    border-bottom: 1px solid var(--border);
    scroll-margin-top: 20px;
}
.main h3 {
    font-size: 19px;
    font-weight: 700;
    color: #dfe9fb;
    margin: 34px 0 12px;
    scroll-margin-top: 20px;
}
.main h3::before {
    content: '';
    display: inline-block;
    width: 4px;
    height: 1em;
    background: var(--accent);
    border-radius: 2px;
    margin-right: 10px;
    vertical-align: -2px;
}
.main p,
.main li {
    color: var(--dim);
}
.main strong {
    color: #fff;
}
.main ul,
.main ol {
    padding-left: 1.4em;
}
.main hr {
    border: none;
    border-top: 1px solid var(--border);
    margin: 36px 0;
}
code {
    font-family: var(--mono);
    font-size: 0.88em;
    background: #0d2038;
    border: 1px solid var(--border);
    border-radius: 5px;
    padding: 1px 6px;
    color: #cfe0ff;
    overflow-wrap: break-word;
    word-break: break-word;
}
pre {
    background: #050d18;
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 16px 18px;
    overflow-x: auto;
    margin: 18px 0;
    line-height: 1.65;
}
pre code {
    background: none;
    border: none;
    padding: 0;
    font-size: 13.5px;
    color: #dbe7ff;
    word-break: normal;
    overflow-wrap: normal;
    white-space: pre;
}
.tok-k {
    color: #7c9eff;
    font-weight: 500;
}
.tok-c {
    color: #7b8fae;
    font-style: italic;
}
.tok-s {
    color: #86efac;
}
.tok-n {
    color: #fdba74;
}
.tok-f {
    color: #c4b5fd;
}
.table-scroll {
    overflow-x: auto;
    margin: 18px 0;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--card);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
}
th,
td {
    padding: 10px 14px;
    text-align: left;
    vertical-align: top;
    border-bottom: 1px solid var(--border);
    color: var(--dim);
    min-width: 80px;
}
th {
    background: var(--card2);
    color: #fff;
    font-weight: 700;
    white-space: nowrap;
}
tr:last-child td {
    border-bottom: none;
}
tbody tr:hover td {
    background: rgba(124, 158, 255, 0.06);
}
table.ref-table td:nth-child(3) {
    word-break: break-all;
    min-width: 260px;
}
tr:target td {
    background: rgba(124, 158, 255, 0.18);
}
.cite {
    font-size: 0.82em;
    font-family: var(--mono);
    padding: 0 2px;
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    margin: 22px 0;
    padding: 22px 16px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 14px;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram p {
    color: inherit;
    margin: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
}
.callout-tip,
.callout-warn,
.callout-note {
    border-radius: 12px;
    padding: 14px 18px 14px 16px;
    margin: 20px 0;
    display: flex;
    gap: 12px;
    align-items: flex-start;
    border: 1px solid var(--border);
    border-left-width: 4px;
}
.callout-tip {
    background: rgba(134, 239, 172, 0.07);
    border-left-color: var(--ok);
}
.callout-warn {
    background: rgba(253, 186, 116, 0.08);
    border-left-color: var(--warn);
}
.callout-note {
    background: rgba(124, 158, 255, 0.08);
    border-left-color: var(--accent);
}
.callout-icon {
    font-size: 20px;
    line-height: 1.6;
    flex: none;
}
.callout-body {
    min-width: 0;
}
.callout-body p {
    margin: 0 0 6px;
}
.callout-body p:last-child {
    margin-bottom: 0;
}
.gloss-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 14px;
    margin: 18px 0;
}
.gloss-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 14px;
    padding: 16px 18px;
    transition:
        border-color 0.2s,
        transform 0.2s;
    min-width: 0;
}
.gloss-card:hover {
    border-color: var(--accent2);
    transform: translateY(-2px);
}
.gloss-top {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 8px;
}
.gloss-icon {
    flex: none;
    width: 38px;
    height: 38px;
    border-radius: 10px;
    background: rgba(124, 158, 255, 0.14);
    border: 1px solid var(--accent2);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 19px;
}
.gloss-term {
    font-weight: 800;
    color: #fff;
    font-size: 15.5px;
    line-height: 1.4;
    overflow-wrap: anywhere;
}
.gloss-term code {
    font-size: 0.9em;
}
.gloss-def {
    margin: 0;
    font-size: 14.5px;
    line-height: 1.75;
    color: var(--dim);
    overflow-wrap: anywhere;
}
.faq-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin: 18px 0;
}
.faq-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 14px;
    overflow: hidden;
}
.faq-card[open] {
    border-color: var(--accent2);
}
.faq-card summary {
    list-style: none;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    cursor: pointer;
    font-weight: 700;
    color: #fff;
    background: rgba(124, 158, 255, 0.06);
}
.faq-card summary::-webkit-details-marker {
    display: none;
}
.faq-card summary:hover {
    background: rgba(124, 158, 255, 0.12);
}
.faq-q {
    flex: 1;
    min-width: 0;
    line-height: 1.55;
}
.faq-chev {
    flex: none;
    color: var(--accent);
    transition: transform 0.2s;
}
.faq-card:not([open]) .faq-chev {
    transform: rotate(-90deg);
}
.faq-a {
    display: flex;
    gap: 12px;
    padding: 14px 18px 16px;
    border-top: 1px solid var(--border);
}
.faq-a-text {
    flex: 1;
    min-width: 0;
    color: var(--dim);
    line-height: 1.8;
}
.qa-badge {
    flex: none;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 13px;
}
.qa-badge.q {
    background: var(--accent);
    color: #07111e;
}
.qa-badge.a {
    background: rgba(134, 239, 172, 0.16);
    color: var(--ok);
    border: 1px solid var(--ok);
}
.checklist-card {
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 20px 22px;
    margin: 18px 0;
}
.checklist-progress {
    margin-bottom: 14px;
}
.cp-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 10px;
}
.cp-title {
    font-weight: 800;
    color: #fff;
}
.cp-right {
    display: flex;
    align-items: center;
    gap: 12px;
}
.cp-pct {
    font-family: var(--mono);
    font-size: 20px;
    font-weight: 500;
    color: var(--accent);
}
.cnt {
    font-size: 13px;
    color: var(--faint);
}
.cp-reset {
    font: inherit;
    font-size: 12.5px;
    color: var(--dim);
    background: transparent;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 4px 12px;
    cursor: pointer;
}
.cp-reset:hover {
    border-color: var(--accent);
    color: #fff;
}
.checklist-progress .bar {
    display: block;
    height: 10px;
    background: #0a1626;
    border-radius: 999px;
    overflow: hidden;
    border: 1px solid var(--border);
}
.checklist-progress .fill {
    display: block;
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, var(--accent2), var(--accent));
    transition: width 0.3s;
}
.checklist-card ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.checklist-card li {
    margin: 0;
}
.ck-row {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 11px 14px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: #0b1829;
    cursor: pointer;
    transition:
        border-color 0.2s,
        background 0.2s;
}
.ck-row:hover {
    border-color: var(--accent2);
    background: #0e2038;
}
.ck-row input {
    position: absolute;
    opacity: 0;
    width: 0;
    height: 0;
}
.ck-box {
    flex: none;
    width: 22px;
    height: 22px;
    margin-top: 3px;
    border-radius: 7px;
    border: 2px solid var(--accent2);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: transparent;
    font-size: 14px;
    font-weight: 800;
    transition: all 0.15s;
}
.ck-box::after {
    content: '✓';
}
.ck-row input:checked ~ .ck-box {
    background: var(--accent);
    border-color: var(--accent);
    color: #07111e;
}
.ck-row input:focus-visible ~ .ck-box {
    outline: 2px solid #fff;
    outline-offset: 2px;
}
.ck-num {
    flex: none;
    font-family: var(--mono);
    font-size: 12.5px;
    color: var(--faint);
    margin-top: 5px;
}
.ck-text {
    flex: 1;
    min-width: 0;
    color: var(--dim);
    line-height: 1.7;
}
.checklist-card li.done .ck-row {
    background: rgba(124, 158, 255, 0.08);
    border-color: var(--accent2);
}
.checklist-card li.done .ck-text {
    color: var(--faint);
    text-decoration: line-through;
    text-decoration-color: var(--accent2);
}
.checklist-card li.done .ck-text strong,
.checklist-card li.done .ck-text code {
    color: inherit;
}
.ck-done {
    margin-top: 14px;
    padding: 12px 16px;
    border-radius: 12px;
    background: rgba(134, 239, 172, 0.1);
    border: 1px solid var(--ok);
    color: var(--ok);
    font-size: 14.5px;
}
.page-footer {
    margin-top: 60px;
    padding-top: 20px;
    border-top: 1px solid var(--border);
    font-size: 13px;
    color: var(--faint);
}
@media (max-width: 900px) {
    .sidebar {
        transform: translateX(-100%);
    }
    .sidebar.open {
        transform: none;
    }
    .scrim.show {
        display: block;
    }
    .nav-toggle {
        display: block;
    }
    .main {
        margin-left: 0;
        padding: 0 18px 60px;
    }
    .hero {
        padding-top: 70px;
    }
    .hero-title {
        font-size: 23px;
    }
    .hero-meta .m {
        border-right: none;
        border-bottom: 1px solid var(--border);
        width: 100%;
        margin-right: 0;
        padding: 8px 0;
    }
    .hero-meta .m:last-child {
        border-bottom: none;
    }
}
